// One Slovenian time zone; city selection changes the photograph and forecast together.
const citySelect=$('#city-select');let cityWeatherTimer,cityWeatherRequest,cityClockOffset=0;
function localNow(){return new Date(Date.now()+cityClockOffset)}
function updateCityClock(){if(!$('#ljubljana-clock'))return;const now=localNow();$('#ljubljana-clock').textContent=new Intl.DateTimeFormat('sl-SI',{timeZone:'Europe/Ljubljana',hour:'2-digit',minute:'2-digit'}).format(now);$('#ljubljana-clock').dateTime=now.toISOString();const date=new Intl.DateTimeFormat('sl-SI',{timeZone:'Europe/Ljubljana',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);$('#city-today').textContent=date.charAt(0).toUpperCase()+date.slice(1);$('#city-zone').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Ljubljana',timeZoneName:'short'}).formatToParts(now).find(p=>p.type==='timeZoneName').value}
const weatherSymbols={sun:'<circle cx="16" cy="15" r="7" fill="#ffbf32"/><path d="M16 3v3m0 18v3M4 15h3m18 0h3M7.5 6.5l2 2m13 13 2 2m-17 0 2-2m13-13 2-2" stroke="#f7a31c" stroke-width="2" stroke-linecap="round"/>',cloud:'<path d="M8 25a7 7 0 1 1 2-13 9 9 0 0 1 17 4 5 5 0 0 1-1 10H8Z" fill="#bfd3e6" stroke="#89abc9" stroke-width=".7"/>',rain:'<path d="m11 26-2 5m9-5-2 5m9-5-2 5" stroke="#42a1f4" stroke-width="2" stroke-linecap="round"/>',snow:'<path d="m11 27 0 4m-2-2h4m8-2v4m-2-2h4" stroke="#7cb9dc" stroke-width="1.5"/>'};
function weatherIcon(symbol){const clear=/clearsky/.test(symbol),part=/fair|partlycloudy/.test(symbol);let shapes=(clear||part?weatherSymbols.sun:'')+(!clear?weatherSymbols.cloud:'');if(/rain|sleet/.test(symbol))shapes+=weatherSymbols.rain;if(/snow/.test(symbol))shapes+=weatherSymbols.snow;if(/thunder/.test(symbol))shapes+='<path d="m20 18-6 8h5l-3 7 10-12h-6l3-3Z" fill="#ffb726"/>';return '<svg viewBox="0 0 36 36" width="34" height="34" aria-hidden="true">'+shapes+'</svg>'}
async function loadCityWeather(city){clearTimeout(cityWeatherTimer);cityWeatherRequest?.abort();cityWeatherRequest=new AbortController();const selected=city.id;say($('#weather-label'),'Vreme · '+city.name);say($('#weather-description'),'Pridobivamo napoved …');say($('#weather-temperature'),'—');say($('#weather-updated'),'Povezujemo se z vremenskim virom …');try{const r=await fetch('/vreme/'+selected+'/',{signal:cityWeatherRequest.signal});const body=await r.json();if(body.server_now){cityClockOffset=new Date(body.server_now).getTime()-Date.now();updateCityClock()}if(!r.ok)throw Error(body.error||'Vremenski podatki trenutno niso na voljo.');if(citySelect.value!==selected)return;const current=body.current;$('#weather-icon').innerHTML=weatherIcon(current.symbol);say($('#weather-description'),current.description);say($('#weather-temperature'),new Intl.NumberFormat('sl-SI',{maximumFractionDigits:0}).format(current.temperature)+'°');const time=new Intl.DateTimeFormat('sl-SI',{timeZone:'Europe/Ljubljana',hour:'2-digit',minute:'2-digit'}).format(new Date(body.updated_at));say($('#weather-updated'),(body.stale?'Zadnja razpoložljiva napoved':'Napoved posodobljena')+' ob '+time);$('.weather-source').classList.toggle('unavailable',body.stale);const more=$('#weather-more');more.replaceChildren();const detail=document.createElement('p');detail.className='muted';detail.textContent=`Veter: ${new Intl.NumberFormat('sl-SI').format(current.wind)} m/s · Vlažnost: ${current.humidity} %`;more.append(detail);const hours=document.createElement('div');hours.className='weather-hours';hours.setAttribute('aria-label','Urna napoved');for(const h of body.hours){const cell=document.createElement('div'),label=document.createElement('time'),temp=document.createElement('strong');label.dateTime=h.at;label.textContent=new Intl.DateTimeFormat('sl-SI',{timeZone:'Europe/Ljubljana',hour:'2-digit',minute:'2-digit'}).format(new Date(h.at));temp.textContent=Math.round(h.temperature)+'°';cell.append(label,temp);cell.title=h.description;hours.append(cell)}more.append(hours);const attribution=document.createElement('a');attribution.href='/fotografije-in-licence/';attribution.textContent='Modelna napoved: MET Norway · CC BY 4.0';attribution.className='muted';more.append(attribution);cityWeatherTimer=setTimeout(()=>{if(!document.hidden)loadCityWeather(city)},Math.max(600000,new Date(body.expires_at)-Date.now()+Math.random()*30000))}catch(error){if(error.name==='AbortError')return;say($('#weather-description'),'Podatki niso na voljo');say($('#weather-updated'),error.message);$('.weather-source').classList.add('unavailable');const p=document.createElement('p');p.className='muted';p.textContent='Vir se trenutno ne odziva. Osvežite stran ali poskusite pozneje. Fotografija prikazuje izbrano mesto, ne trenutnega vremena.';$('#weather-more').replaceChildren(p);cityWeatherTimer=setTimeout(()=>{if(!document.hidden)loadCityWeather(city)},600000)}}
if(citySelect){updateCityClock();setInterval(updateCityClock,1000);fetch($('#city-card').dataset.citiesUrl).then(r=>{if(!r.ok)throw Error();return r.json()}).then(cities=>{function changeCity(){const city=cities.find(c=>c.id===citySelect.value)||cities.find(c=>c.id==='ljubljana');if(rememberCityAllowed())store.set('k365.city',city.id);const img=$('#city-photo');img.src=city.photo;img.alt=city.name+' – pogled na mesto';say($('#city-caption'),city.name+', Slovenija');$('#city-credit').href=city.credit;loadCityWeather(city)}const saved=rememberCityAllowed()?store.get('k365.city','ljubljana'):'ljubljana';document.addEventListener('k365:consent',e=>{if(e.detail.preferences)store.set('k365.city',citySelect.value)});if(cities.some(c=>c.id===saved))citySelect.value=saved;citySelect.addEventListener('change',changeCity);document.addEventListener('visibilitychange',()=>{if(!document.hidden)changeCity()});changeCity()}).catch(()=>say($('#weather-updated'),'Seznama mest ni mogoče naložiti. Osvežite stran.'))}
