function initDateCalculator(root){
 const form=root.querySelector('[data-date-form]');if(!form)return;
 const tabs=[...root.querySelectorAll('[data-date-mode]')],panes=[...root.querySelectorAll('[data-date-pane]')];
 const result=root.querySelector('[data-date-result]'),summary=result.querySelector('[data-result-summary]'),primary=result.querySelector('[data-result-primary]'),caption=result.querySelector('[data-result-caption]'),note=result.querySelector('[data-result-note]');
 const labels={one:result.querySelector('[data-stat-label="one"]'),two:result.querySelector('[data-stat-label="two"]'),three:result.querySelector('[data-stat-label="three"]'),four:result.querySelector('[data-stat-label="four"]')};
 const stats={one:result.querySelector('[data-stat="one"]'),two:result.querySelector('[data-stat="two"]'),three:result.querySelector('[data-stat="three"]'),four:result.querySelector('[data-stat="four"]')};
 const formatter=new Intl.DateTimeFormat('sl-SI',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
 const weekdayFormatter=new Intl.DateTimeFormat('sl-SI',{weekday:'long',timeZone:'UTC'});
 const numberFormatter=new Intl.NumberFormat('sl-SI',{maximumFractionDigits:2});
 const dateInput=(value)=>{const match=/^(\d{4})-(\d{2})-(\d{2})$/.exec(value||'');if(!match)return null;const date=new Date(Date.UTC(+match[1],+match[2]-1,+match[3]));return date.getUTCFullYear()===+match[1]&&date.getUTCMonth()===+match[2]-1&&date.getUTCDate()===+match[3]?date:null};
 const dateISO=(date)=>date.toISOString().slice(0,10);
 const dayDiff=(a,b)=>Math.round((b-a)/86400000);
 const dateText=(date)=>formatter.format(date);
 const weekday=(date)=>{const value=weekdayFormatter.format(date);return value.charAt(0).toLocaleUpperCase('sl-SI')+value.slice(1)};
 const plural=(n,forms)=>{const value=Math.abs(n),last=value%10,lastTwo=value%100;if(last===1&&lastTwo!==11)return forms[0];if(last===2&&lastTwo!==12)return forms[1];if((last===3||last===4)&&!(lastTwo>=13&&lastTwo<=14))return forms[2];return forms[3]};
 const countText=(n,unit)=>numberFormatter.format(n)+' '+plural(n,unit);
 const dayForms=['dan','dneva','dnevi','dni'],weekForms=['teden','tedna','tedni','tednov'],monthForms=['mesec','meseca','meseci','mesecev'],hourForms=['ura','uri','ure','ur'];
 const addMonths=(date,amount)=>{const first=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+amount,1));const last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();return new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth(),Math.min(date.getUTCDate(),last)))};
 const monthBreakdown=(a,b)=>{const first=a<=b?a:b,last=a<=b?b:a;let months=(last.getUTCFullYear()-first.getUTCFullYear())*12+last.getUTCMonth()-first.getUTCMonth();let anchor=addMonths(first,months);if(anchor>last){months-=1;anchor=addMonths(first,months)}return {months,days:dayDiff(anchor,last)}};
 const setMode=(mode,focus=false)=>{if(!['difference','add','workdays'].includes(mode))mode='difference';form.dataset.mode=mode;form.querySelector('[data-date-tool]').value=mode==='workdays'?'workdays':'date';tabs.forEach(tab=>{const active=tab.dataset.dateMode===mode;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;if(active&&focus)tab.focus()});panes.forEach(pane=>{const active=pane.dataset.datePane===mode;pane.hidden=!active;pane.disabled=!active})};
 const setStats=(values,names)=>{for(const key of Object.keys(stats)){if(names?.[key])labels[key].textContent=names[key];stats[key].textContent=values[key]??'—'}};
 const clearNote=()=>{note.hidden=true;note.textContent='';root.classList.remove('date-tool--error')};
 const showError=(message)=>{root.classList.add('date-tool--error');result.querySelector('[data-result-label]').textContent='PREVERITE VNOS';result.querySelector('[data-result-title]').textContent='Izračun ni uspel';summary.textContent=message;primary.textContent='—';caption.textContent='Popravite vnos in poskusite znova.';setStats({});note.hidden=true};
 const renderDifference=()=>{const from=dateInput(form.querySelector('[data-date-from]').value),to=dateInput(form.querySelector('[data-date-to]').value);if(!from||!to)throw new Error('Vnesite veljavna začetni in končni datum.');const difference=dayDiff(from,to),inclusive=form.querySelector('[data-date-inclusive]').checked,signed=difference+(inclusive?(difference<0?-1:1):0),elapsed=Math.abs(difference),total=Math.abs(signed),weeks=Math.floor(total/7),days=total%7,parts=monthBreakdown(from,to);result.querySelector('[data-result-label]').textContent='VAŠ REZULTAT';result.querySelector('[data-result-title]').textContent='Razlika med datumoma';summary.textContent=dateText(from)+' – '+dateText(to)+(inclusive?' · vključena oba mejna dneva':'');primary.textContent=(signed<0?'− ':'')+countText(total,dayForms);caption.textContent=(signed<0?'končni datum je pred začetnim datumom · ':'')+(inclusive?'vključno z obema datumoma':'polni dnevi med datumoma')+' · '+countText(elapsed,dayForms)+' razlike';setStats({one:numberFormatter.format(weeks)+' '+plural(weeks,weekForms)+', '+countText(days,dayForms),two:numberFormatter.format(parts.months)+' '+plural(parts.months,monthForms)+', '+countText(parts.days,dayForms),three:weekday(from),four:weekday(to)});clearNote()};
 const renderShift=()=>{const from=dateInput(form.querySelector('[data-shift-from]').value),amount=Number(form.querySelector('[data-date-delta]').value),unit=form.querySelector('[data-date-unit]').value;if(!from||!Number.isInteger(amount)||Math.abs(amount)>100000)throw new Error('Vnesite veljaven datum in celo število med −100.000 in 100.000.');let target;if(unit==='months')target=addMonths(from,amount);else target=new Date(from.getTime()+(amount*(unit==='weeks'?7:1))*86400000);if(!Number.isFinite(target.getTime()))throw new Error('Izbrani premik je zunaj podprtega razpona.');const unitName=unit==='months'?plural(Math.abs(amount),monthForms):unit==='weeks'?plural(Math.abs(amount),weekForms):plural(Math.abs(amount),dayForms);result.querySelector('[data-result-label]').textContent='VAŠ REZULTAT';result.querySelector('[data-result-title]').textContent='Datum po premiku';summary.textContent=dateText(from)+' '+(amount<0?'−':'＋')+' '+numberFormatter.format(Math.abs(amount))+' '+unitName;primary.textContent=dateText(target);caption.textContent=weekday(target)+' · '+dateISO(target);setStats({one:weekday(target),two:numberFormatter.format(Math.abs(amount))+' '+unitName,three:dateISO(from),four:dateISO(target)},{one:'Dan v tednu',two:'Premik',three:'Izhodišče',four:'Ciljni datum'});clearNote()};
 const renderWorkdays=async()=>{const from=dateInput(form.querySelector('[data-work-from]').value),to=dateInput(form.querySelector('[data-work-to]').value);if(!from||!to)throw new Error('Vnesite veljavna začetni in končni datum.');if(from>to)throw new Error('Končni datum ne sme biti pred začetnim datumom.');const payload=formObject(form);payload.tool='workdays';const body=await api(form.action,payload);const data=body.workdays;if(!data)throw new Error(body.result||'Podrobnosti izračuna niso na voljo.');result.querySelector('[data-result-label]').textContent='VAŠ REZULTAT';result.querySelector('[data-result-title]').textContent='Delovni dnevi';summary.textContent=dateText(from)+' – '+dateText(to);primary.textContent=countText(data.working_days,['delovni dan','delovna dneva','delovni dnevi','delovnih dni']);caption.textContent=numberFormatter.format(data.hours)+' '+plural(data.hours,hourForms)+' po '+numberFormatter.format(data.working_days?data.hours/data.working_days:0)+' ur na delovni dan';setStats({one:numberFormatter.format(data.calendar_days),two:numberFormatter.format(data.working_days),three:numberFormatter.format(data.hours)+' '+plural(data.hours,hourForms),four:numberFormatter.format((data.excluded_holidays||[]).length)},{one:'Všteti koledarski dnevi',two:'Delovni dnevi',three:'Skupno delovnih ur',four:'Izločeni prazniki'});if(data.excluded_holidays?.length){note.textContent='Izločeni prazniki: '+data.excluded_holidays.map(value=>dateText(dateInput(value))).join(', ');note.hidden=false}else clearNote()};
 const run=async()=>{const mode=form.dataset.mode;form.querySelector('[data-date-submit]').disabled=true;try{if(mode==='difference')renderDifference();else if(mode==='add')renderShift();else await renderWorkdays()}catch(error){showError(error.message||'Zahteva ni uspela. Poskusite znova.')}finally{form.querySelector('[data-date-submit]').disabled=false}};
 tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>{setMode(tab.dataset.dateMode);run()});tab.addEventListener('keydown',event=>{let target=index;if(event.key==='ArrowRight')target=(index+1)%tabs.length;else if(event.key==='ArrowLeft')target=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')target=0;else if(event.key==='End')target=tabs.length-1;else return;event.preventDefault();setMode(tabs[target].dataset.dateMode,true);run()})});
 root.querySelector('[data-date-swap]').addEventListener('click',()=>{const a=form.querySelector('[data-date-from]'),b=form.querySelector('[data-date-to]'),value=a.value;a.value=b.value;b.value=value;run()});
 root.querySelector('[data-work-swap]').addEventListener('click',()=>{const a=form.querySelector('[data-work-from]'),b=form.querySelector('[data-work-to]'),value=a.value;a.value=b.value;b.value=value;run()});
 root.querySelectorAll('[data-date-preset]').forEach(button=>button.addEventListener('click',()=>{const from=dateInput(form.querySelector('[data-date-from]').value);if(!from)return;form.querySelector('[data-date-to]').value=dateISO(new Date(from.getTime()+Number(button.dataset.datePreset)*86400000));run()}));
 form.addEventListener('submit',event=>{event.preventDefault();run()});
 root.querySelector('[data-copy-result]').addEventListener('click',async event=>{const textToCopy=[summary.textContent,primary.textContent,caption.textContent,...Object.keys(stats).map(key=>labels[key].textContent+': '+stats[key].textContent),note.hidden?'':note.textContent].filter(Boolean).join('\n');try{await navigator.clipboard.writeText(textToCopy);event.currentTarget.textContent='Kopirano ✓';setTimeout(()=>event.currentTarget.textContent='Kopiraj rezultat',1800)}catch{showError('Kopiranje ni bilo mogoče. Označite rezultat in ga kopirajte ročno.')}});
 root.querySelector('[data-copy-link]').addEventListener('click',async event=>{const url=new URL(location.href);url.search='';url.searchParams.set('calc',form.dataset.mode);const mode=form.dataset.mode;if(mode==='difference'){url.searchParams.set('from',form.querySelector('[data-date-from]').value);url.searchParams.set('to',form.querySelector('[data-date-to]').value);if(form.querySelector('[data-date-inclusive]').checked)url.searchParams.set('inclusive','1')}else if(mode==='add'){url.searchParams.set('from',form.querySelector('[data-shift-from]').value);url.searchParams.set('delta',form.querySelector('[data-date-delta]').value);url.searchParams.set('unit',form.querySelector('[data-date-unit]').value)}else{url.searchParams.set('from',form.querySelector('[data-work-from]').value);url.searchParams.set('to',form.querySelector('[data-work-to]').value);url.searchParams.set('weekdays',[...form.querySelectorAll('[data-date-pane="workdays"] input[name="weekdays[]"]:checked')].map(input=>input.value).join(','));url.searchParams.set('hours',form.querySelector('[data-work-hours]').value);if(form.querySelector('[data-date-pane="workdays"] input[name="exclude_holidays"]').checked)url.searchParams.set('holidays','1');if(!form.querySelector('[data-date-pane="workdays"] input[name="include_start"]').checked)url.searchParams.set('start','0');if(!form.querySelector('[data-date-pane="workdays"] input[name="include_end"]').checked)url.searchParams.set('end','0')}try{await navigator.clipboard.writeText(url.toString());event.currentTarget.textContent='Povezava kopirana ✓';setTimeout(()=>event.currentTarget.textContent='Kopiraj povezavo',1800)}catch{showError('Povezave ni bilo mogoče kopirati. Poskusite znova.')}});
 const params=new URLSearchParams(location.search),mode=params.get('calc');if(mode){setMode(mode);const from=params.get('from'),to=params.get('to');if(mode==='difference'){if(from)form.querySelector('[data-date-from]').value=from;if(to)form.querySelector('[data-date-to]').value=to;form.querySelector('[data-date-inclusive]').checked=params.get('inclusive')==='1'}else if(mode==='add'){if(from)form.querySelector('[data-shift-from]').value=from;if(params.has('delta'))form.querySelector('[data-date-delta]').value=params.get('delta');if(['days','weeks','months'].includes(params.get('unit')))form.querySelector('[data-date-unit]').value=params.get('unit')}else if(mode==='workdays'){if(from)form.querySelector('[data-work-from]').value=from;if(to)form.querySelector('[data-work-to]').value=to;if(params.has('weekdays')){const chosen=params.get('weekdays').split(',');form.querySelectorAll('[data-date-pane="workdays"] input[name="weekdays[]"]').forEach(input=>input.checked=chosen.includes(input.value))}if(params.has('hours'))form.querySelector('[data-work-hours]').value=params.get('hours');form.querySelector('[data-date-pane="workdays"] input[name="exclude_holidays"]').checked=params.get('holidays')==='1';form.querySelector('[data-date-pane="workdays"] input[name="include_start"]').checked=params.get('start')!=='0';form.querySelector('[data-date-pane="workdays"] input[name="include_end"]').checked=params.get('end')!=='0'}}
 setMode(mode||'difference');run();
}
$$('[data-date-calculator]').forEach(initDateCalculator);
